package com.myf.report.config; import org.springframework.amqp.core.*; import org.springframework.context.annotation.*; @Configuration public class RabbitConfig{public static final String EXCHANGE="myf.events",QUEUE="myf.sale.created";@Bean TopicExchange ex(){return new TopicExchange(EXCHANGE,true,false);}@Bean Queue q(){return new Queue(QUEUE,true);}@Bean Binding b(Queue q,TopicExchange ex){return BindingBuilder.bind(q).to(ex).with("sale.created");}}